// Curated homepage hero rotation.
//
// Every slide is a real Arees / Dahab product photograph from /public. Desktop
// uses the wide landscape original; phones use the matching 2:3 portrait crop
// generated by `npm run hero:mobile`, so the bottles stay framed instead of
// being cropped out on narrow screens.
//
// `focus`, `tabletFocus` and `mobileFocus` are object-position values. They are
// tuned per photograph so the bottle stays clear of the left-hand copy column
// on desktop and tablet, and above the copy block on phones.

const HOME_HERO_SLIDES = [
  {
    src: '/Hero.webp',
    mobileWebp: '/Hero-mobile.webp',
    alt: 'Arees Perfumes — Aseel attar and Pink Musk roll-on collection',
    brandName: 'Arees Perfumes',
    focus: '58% 45%',
    tabletFocus: '62% 44%',
    mobileFocus: '50% 42%',
    brightness: 1,
    duration: 6500,
  },
  {
    src: '/arees12ml-hero.webp',
    mobileWebp: '/arees12ml-hero-mobile.webp',
    alt: 'Arees 12ml non-alcoholic parfum bottle',
    brandName: 'Arees 12ml',
    focus: '58% 50%',
    tabletFocus: '62% 48%',
    mobileFocus: '50% 40%',
    brightness: 1,
    duration: 6000,
  },
  {
    src: '/areesluxury-hero.webp',
    mobileWebp: '/areesluxury-hero-mobile.webp',
    alt: 'Arees Luxury eau de parfum bottle',
    brandName: 'Arees Luxury',
    focus: '66% 52%',
    tabletFocus: '66% 50%',
    mobileFocus: '50% 42%',
    brightness: 1,
    duration: 6000,
  },
  {
    src: '/bakhoor-hero.webp',
    mobileWebp: '/bakhoor-hero-mobile.webp',
    alt: 'Arees Bakhoor Ad Dawli incense collection',
    brandName: 'Arees Bakhoor',
    focus: '54% 48%',
    tabletFocus: '57% 48%',
    mobileFocus: '50% 42%',
    brightness: 0.95,
    duration: 6000,
  },
  {
    src: '/Dahab-hero.webp',
    mobileWebp: '/Dahab-hero-mobile.webp',
    alt: 'Dahab 6ml roll-on perfume collection',
    brandName: 'Dahab 6ml',
    focus: '58% 48%',
    tabletFocus: '61% 48%',
    mobileFocus: '50% 42%',
    brightness: 1,
    duration: 6000,
  },
]

/**
 * Build the homepage hero slides.
 *
 * The order is fixed: the Arees signature image first (also the LCP preload in
 * index.html), followed by the four product lines.
 *
 * @returns {Array<Object>} copies of the curated slide metadata
 */
export function buildHomeHeroImages() {
  return HOME_HERO_SLIDES.map((slide) => ({ ...slide }))
}
